import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system_name = platform.system().lower()
    if "windows" in system_name:
        cmd = ["powershell", "-Command", "(Get-Counter '\\Processor(_Total)\\% Processor Time').CounterSamples.CookedValue"]
    else:
        cmd = ["sh", "-c", "if command -v mpstat >/dev/null 2>&1; then mpstat 1 1 | awk 'END{print 100-$NF}'; else top -bn1 | awk '/Cpu\\(s\\)/{print 100-$8}'; fi"]
    data = []
    start = time.time()
    while True:
        now = time.time()
        if now - start >= duration:
            break
        timestamp = now
        cpu_usage = None
        try:
            output = subprocess.check_output(cmd, stderr=subprocess.DEVNULL)
            text = output.decode("utf-8").strip()
            if text:
                text = text.splitlines()[-1].strip()
                text = text.replace(",", ".")
                for ch in text:
                    if (ch < "0" or ch > "9") and ch not in ".-":
                        text = text.replace(ch, " ")
                parts = [p for p in text.split() if p]
                if parts:
                    cpu_usage = float(parts[0])
        except Exception:
            cpu_usage = None
        data.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f)
    except IOError:
        return None
    return LOGFILE_PATH

