LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system = platform.system().lower()
    records = []
    start_time = time.time()
    while True:
        current_time = time.time()
        if current_time - start_time >= duration and records:
            break
        timestamp = current_time
        cpu_usage = None
        try:
            if "windows" in system:
                result = subprocess.run(["wmic", "cpu", "get", "loadpercentage"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                output = result.stdout.strip().splitlines()
                if len(output) >= 2:
                    value = output[1].strip()
                    cpu_usage = float(value)
            else:
                result = subprocess.run(["top", "-bn1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                out = result.stdout.lower()
                cpu_line = ""
                for line in out.splitlines():
                    if "cpu(s)" in line or line.strip().startswith("%cpu"):
                        cpu_line = line
                        break
                if cpu_line:
                    if "id" in cpu_line:
                        parts = cpu_line.replace(",", " ").split()
                        idle = None
                        for i, p in enumerate(parts):
                            if p.startswith("id"):
                                try:
                                    idle = float(parts[i - 1])
                                except:
                                    idle = None
                                break
                        if idle is not None:
                            cpu_usage = 100.0 - idle
                    if cpu_usage is None:
                        nums = []
                        for token in cpu_line.replace(",", " ").split():
                            try:
                                nums.append(float(token))
                            except:
                                continue
                        if nums:
                            cpu_usage = nums[0]
        except Exception:
            cpu_usage = None
        if cpu_usage is not None:
            records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

