        cmd = [
            "powershell",
            "-Command",
            "(Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor | Where-Object {$_.Name -eq '_Total'}).PercentProcessorTime"
        ]
    else:
        cmd = [
            "sh",
            "-c",
            "top -bn1 | grep '%Cpu' || top -bn1 | grep 'Cpu(s)'"
        ]
    records = []
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time >= duration:
            break
        timestamp = now
        try:
