            if system == "Windows":
                try:
                    cpu_usage = float(output_stripped)
                except ValueError:
                    continue
            else:
                line = output_stripped.replace(",", ".")
                parts = line.split()
                idle = None
                for p in parts:
                    if p.endswith("id"):
                        try:
                            idle = float(p[:-2])
                        except ValueError:
                            idle = None
                        break
                if idle is None:
                    continue
                cpu_usage = 100.0 - idle
            records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
