import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    try:
        process = subprocess.Popen(["Rscript", r_script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except Exception:
        return False, "File not generated within the specified duration."
    start_time = time.time()
    matched = False
    while time.time() - start_time < duration:
        if "*" in output_path or "?" in output_path or "[" in output_path:
            files = glob.glob(output_path)
            if files:
                matched = True
                break
        else:
            if os.path.exists(output_path):
                matched = True
                break
        time.sleep(0.5)
    if process.poll() is None:
        try:
            process.terminate()
        except Exception:
            pass
    if matched:
        return True, "File generated successfully within the specified duration."
    else:
        return False, "File not generated within the specified duration."

import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path:
        raise FileNotFoundError("Empty script path")
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"{script_path} does not exist")
    if not isinstance(timeout, int) or timeout <= 0:
        raise TypeError("timeout must be a positive integer")
    proc = subprocess.Popen(
        ["python", script_path],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE
    )
    timeout_triggered = {"value": False}
    def kill_proc():
        if proc.poll() is None:
            timeout_triggered["value"] = True
            proc.terminate()
    timer = threading.Timer(timeout, kill_proc)
    timer.start()
    try:
        proc.communicate()
    finally:
        timer.cancel()
    if timeout_triggered["value"]:
        return "Terminating process due to timeout."
    return "Script executed successfully."

import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str):
        raise TypeError("r_script_path and output_path must be strings")
    if not isinstance(duration, int):
        raise TypeError("duration must be an integer")
    if r_script_path.strip() == "" or output_path.strip() == "":
        raise ValueError("r_script_path and output_path must be non-empty")
    if duration < 0:
        raise ValueError("duration must be non-negative")
    if not os.path.exists(r_script_path):
        raise FileNotFoundError(f"R script not found: {r_script_path}")
    try:
        process = subprocess.Popen(["Rscript", r_script_path])
    except Exception as e:
        return False, "File not generated within the specified duration."
    start_time = time.time()
    has_wildcard = any(c in output_path for c in ["*", "?", "["])
    while time.time() - start_time <= duration:
        if has_wildcard:
            matches = glob.glob(output_path)
            if matches:
                return True, "File generated successfully within the specified duration."
        else:
            if os.path.exists(output_path):
                return True, "File generated successfully within the specified duration."
        time.sleep(0.5)
    return False, "File not generated within the specified duration."

