def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str):
        raise TypeError("r_script_path and output_path must be strings")
    if not isinstance(duration, int):
        raise TypeError("duration must be an integer")
    if duration < 0:
        raise ValueError("duration must be non-negative")
    if not r_script_path or not os.path.isfile(r_script_path):
        raise OSError("Invalid R script path")
    try:
        process = subprocess.Popen(["Rscript", r_script_path])
    except Exception as e:
        return False, "File not generated within the specified duration."
    pattern_mode = False
    single_file_mode = False
    output_path_norm = os.path.normpath(output_path)
    if any(ch in output_path_norm for ch in ["*", "?", "["]):
        pattern_mode = True
        pattern = output_path_norm
    else:
        if os.path.isdir(output_path_norm):
            pattern_mode = True
            pattern = os.path.join(output_path_norm, "*")
        else:
            single_file_mode = True
            target_file = output_path_norm
    start_time = time.time()
    success = False
    msg = "File not generated within the specified duration."
    while time.time() - start_time <= duration:
        if pattern_mode:
            matches = glob.glob(pattern)
            if matches:
                success = True
                msg = "File generated successfully within the specified duration."
                break
        elif single_file_mode:
            if os.path.exists(target_file):
                success = True
                msg = "File generated successfully within the specified duration."
                break
        time.sleep(0.5)
    try:
        if process.poll() is None:
            try:
                process.wait(timeout=1)
            except Exception:
                pass
    except Exception:
        pass
    return success, msg

