import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str):
        raise TypeError("r_script_path and output_path must be strings")
    if r_script_path.strip() == "" or output_path.strip() == "":
        raise TypeError("r_script_path and output_path must be non-empty strings")
    if not isinstance(duration, int):
        raise TypeError("duration must be an integer")
    if duration < 0:
        raise ValueError("duration must be non-negative")
    r_script_path = os.path.abspath(r_script_path)
    output_path = os.path.abspath(output_path)
    if not os.path.isfile(r_script_path):
        raise FileNotFoundError(f"R script not found: {r_script_path}")
    try:
        process = subprocess.Popen(["Rscript", r_script_path])
    except Exception:
        return False, "File not generated within the specified duration."
    start_time = time.time()
    end_time = start_time + duration
    while time.time() <= end_time:
        matches = glob.glob(output_path)
        if matches:
            return True, "File generated successfully within the specified duration."
        time.sleep(0.5)
    matches = glob.glob(output_path)
    if matches:
        return True, "File generated successfully within the specified duration."
    return False, "File not generated within the specified duration."

import subprocess
import os
import json
from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if os.path.isabs(script_name):
        script_path = script_name
    else:
        script_path = os.path.join(os.getcwd(), script_name)
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    start_dt = datetime.now()
    start_time = start_dt.strftime('%Y-%m-%d %H:%M:%S')
    try:
        completed = subprocess.run(script_path, shell=True)
    except Exception as e:
        raise RuntimeError(f"Error executing script: {e}")
    end_dt = datetime.now()
    end_time = end_dt.strftime('%Y-%m-%d %H:%M:%S')
    result = {
        'start_time': start_time,
        'end_time': end_time,
        'exit_status': completed.returncode
    }
    logs = []
    if os.path.exists(log_file):
        try:
            with open(log_file, 'r') as f:
                data = f.read().strip()
                if data:
                    logs = json.loads(data)
        except Exception:
            logs = []
    if isinstance(logs, list):
        logs.append(result)
    else:
        logs = [result]
    os.makedirs(os.path.dirname(log_file), exist_ok=True)
    with open(log_file, 'w') as f:
        json.dump(logs, f)
    if completed.returncode != 0:
        raise RuntimeError(f"Script exited with status {completed.returncode}")
    return result

