import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    results = {}
    for host in network.hosts():
        ip_str = str(host)
        cmd = ['ping']
        if subprocess.os.name == 'nt':
            cmd += ['-n', '1', '-w', '1000', ip_str]
        else:
            cmd += ['-c', '1', '-W', '1', ip_str]
        completed = subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=True)
        results[ip_str] = completed.returncode == 0
    return results

