import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    if not isinstance(process_name, str) or not process_name.strip():
        raise ValueError("process_name must be a non-empty string")
    name_lower = process_name.lower()
    matched_pids = []
    for proc in psutil.process_iter(attrs=["name", "cmdline"]):
        try:
            info = proc.info
            pname = info.get("name") or ""
            cmdline = info.get("cmdline") or []
            if pname.lower() == name_lower:
                matched_pids.append(proc.pid)
                continue
            if cmdline:
                first = cmdline[0].lower()
                if first.endswith(process_name.lower()) or first == name_lower:
                    matched_pids.append(proc.pid)
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue
    if not matched_pids:
        subprocess.Popen([process_name])
        time.sleep(0.1)
        return f"Process not found. Starting {process_name}."
    processes = []
    for pid in matched_pids:
        try:
            processes.append(psutil.Process(pid))
        except psutil.NoSuchProcess:
            continue
    for p in processes:
        try:
            p.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue
    gone, alive = psutil.wait_procs(processes, timeout=3)
    for p in alive:
        try:
            p.kill()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue
    subprocess.Popen([process_name])
    time.sleep(0.1)
    return f"Process found. Restarting {process_name}."

