import threading
def task_func(file_list):
    if file_list is None:
        return []
    processes = []
    results = [None] * len(file_list)
    threads = []
    def worker(proc, idx):
        code = proc.wait()
        results[idx] = code
    for idx, path in enumerate(file_list):
        try:
            proc = subprocess.Popen(path, shell=True)
            processes.append(proc)
            t = threading.Thread(target=worker, args=(proc, idx))
            t.start()
