from glob import glob
def task_func(src_folder, dst_folder):
    if not isinstance(src_folder, str) or not isinstance(dst_folder, str) or not src_folder or not dst_folder:
        raise TypeError("src_folder and dst_folder must be non-empty strings")
    src_folder = os.path.abspath(src_folder)
    dst_folder = os.path.abspath(dst_folder)
    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist or is not a directory: {src_folder}",
            "failed_files": []
        }
    os.makedirs(dst_folder, exist_ok=True)
    all_paths = [p for p in glob(os.path.join(src_folder, "*")) if os.path.isfile(p)]
    if not all_paths:
        return {
            "success": True,
            "message": "No files found to compress.",
            "failed_files": []
        }
    processes = []
    for path in all_paths:
        try:
            proc = subprocess.Popen(["gzip", "-k", path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            processes.append((path, proc))
        except Exception:
            processes.append((path, None))
    failed_files = []
    for path, proc in processes:
        if proc is None:
            failed_files.append(os.path.basename(path))
            continue
        proc.communicate()
        if proc.returncode != 0:
            failed_files.append(os.path.basename(path))
    for path in all_paths:
        filename = os.path.basename(path)
        if filename in failed_files:
            continue
        gz_path = path + ".gz"
        if not os.path.exists(gz_path):
            if filename not in failed_files:
                failed_files.append(filename)
            continue
        try:
            shutil.move(gz_path, os.path.join(dst_folder, os.path.basename(gz_path)))
        except Exception:
            if filename not in failed_files:
                failed_files.append(filename)
    success = len(failed_files) == 0
    if success:
        message = "All files were compressed and moved successfully."
    else:
        message = f"Some files failed to compress or move: {len(failed_files)} file(s)."
    return {
        "success": success,
        "message": message,
        "failed_files": failed_files
    }

