        if len(failed_files) == len(files):
            message = "Failed to compress or move all files"
        else:
            message = "Some files failed to compress or move"
        success = False
    else:
        message = "All files compressed and moved successfully"
        success = True
    return {"success": success, "message": message, "failed_files": failed_files}

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not isinstance(src_folder, str) or not isinstance(dst_folder, str):
        raise ValueError("Source and destination folders must be strings")
    src_folder = os.path.abspath(src_folder)
    dst_folder = os.path.abspath(dst_folder)
    if not src_folder or not os.path.isdir(src_folder):
        raise ValueError("Invalid source folder")
    if not dst_folder:
        raise ValueError("Invalid destination folder")
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)
    pattern = os.path.join(src_folder, "*")
    files = [f for f in glob(pattern) if os.path.isfile(f)]
    failed_files = []
    if not files:
        return {
            "success": True,
            "message": "No files found to compress",
            "failed_files": failed_files
        }
    for file_path in files:
        basename = os.path.basename(file_path)
        try:
            proc = subprocess.Popen(["gzip", "-k", file_path])
            return_code = proc.wait()
            if return_code != 0:
                failed_files.append(basename)
                continue
            compressed_path = file_path + ".gz"
            if not os.path.exists(compressed_path):
                failed_files.append(basename)
                continue
            dst_path = os.path.join(dst_folder, os.path.basename(compressed_path))
            try:
                shutil.move(compressed_path, dst_path)
            except Exception:
                failed_files.append(basename)
        except Exception:
            failed_files.append(basename)
    success = len(failed_files) == 0
    if success:
        message = "All files were compressed and moved successfully"
    else:
        message = f"Some files failed to compress or move: {len(failed_files)} failures"
    return {
        "success": success,
        "message": message,
        "failed_files": failed_files
    }

import subprocess
import os
import time
from datetime import datetime
def task_func(script_dir, scripts, delay):
    if delay < 0:
        raise ValueError("Delay cannot be negative")
    if not scripts:
        raise ValueError("No scripts provided")
    timestamps = []
    script_dir = os.path.normpath(script_dir)
    for i, script in enumerate(scripts):
        script_path = os.path.join(script_dir, script)
        start_time = datetime.now().isoformat()
        timestamps.append(start_time)
        try:
            subprocess.run([script_path], check=False)
        except Exception:
            pass
        if i != len(scripts) - 1:
            time.sleep(delay)
    return timestamps

