import os
import glob
ARCHIVE_DIR = '/tmp/archive'
def task_func(pattern):
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    files = glob.glob(pattern)
    if not os.path.exists(ARCHIVE_DIR):
        os.makedirs(ARCHIVE_DIR, exist_ok=True)
    base = os.path.basename(pattern)
    if not base:
        base = "archive"
    archive_name = base.replace(os.path.sep, "_")
    if archive_name in ("*", "."):
        archive_name = "archive"
    archive_file = os.path.join(ARCHIVE_DIR, archive_name + ".tar.gz")
    if not files:
        return archive_file
    common_dir = os.path.commonpath(files)
    rel_files = []
    for f in files:
        try:
            rel_files.append(os.path.relpath(f, common_dir))
        except ValueError:
            common_dir = os.getcwd()
            rel_files = [os.path.relpath(x, common_dir) for x in files]
            break
    cmd = ["tar", "-czf", archive_file] + rel_files
    result = subprocess.run(cmd, cwd=common_dir, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if result.returncode != 0:
        raise OSError("Failed to create archive: " + result.stderr.decode("utf-8", errors="ignore"))
    for f in files:
        if os.path.exists(f):
            os.remove(f)
    return archive_file

